package org.springframework.samples.petclinic.util;

import java.util.Map;

/**
 * Derives an owner's {@code locality}: the canonical region. The postcode is preferred,
 * looked up by range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); when it is absent or
 * in no known range the fixed city-to-region table is used instead. Anything unresolved
 * resolves to {@code "UNKNOWN"}.
 */
public final class Locality {

    private static final Map<String, String> CITY_REGION =
        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** Postcode "hundreds" band (postcode / 100) -> region. */
    private static final Map<Integer, String> BAND_REGION =
        Map.of(20, "NSW", 30, "VIC", 40, "QLD");

    private Locality() {
    }

    /** The canonical region for {@code city}, or {@code "UNKNOWN"} when it is not mapped. */
    public static String of(String city) {
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }

    /** The region for {@code postcode} (preferred), falling back to {@code city}. */
    public static String of(String city, String postcode) {
        String region = byPostcode(postcode);
        return region != null ? region : of(city);
    }

    /** The region whose range contains {@code postcode}, or {@code null} when none does. */
    private static String byPostcode(String postcode) {
        if (postcode == null) {
            return null;
        }
        return BAND_REGION.get(Integer.parseInt(postcode) / 100);
    }
}
package org.springframework.samples.petclinic.util;

import java.util.Collection;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Decides the GOLD membership tier: an owner qualifies once their household (owners
 * sharing the same {@link Household} id, i.e. the same normalized last name and
 * postcode) has three or more members. When it does not apply, the mapper's existing
 * BRONZE/SILVER rules stand.
 */
public final class GoldTier {

    private GoldTier() {
    }

    /** True when {@code owner}'s household has 3+ members among {@code allOwners}. */
    public static boolean qualifies(Owner owner, Collection<Owner> allOwners) {
        String household = Household.idFor(owner);
        return allOwners.stream()
            .filter(o -> household.equals(Household.idFor(o)))
            .count() >= 3;
    }
}
package org.springframework.samples.petclinic.util;

import java.time.LocalDate;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Computes an owner's membership standing as a points total and the level it maps to.
 * Points start at 0 and accrue: +2 for a present email, +1 when the owner has no
 * namesakes, +2 for a household of three or more (see {@link GoldTier}), and +3 for
 * tenure spanning more than one elapsed fiscal year (see {@link FiscalYear}). Levels
 * map from points: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6+).
 */
public final class Membership {

    private Membership() {
    }

    /** Total membership points for {@code owner}. */
    public static int points(Owner owner) {
        int points = 0;
        if (owner.getEmail() != null) {
            points += 2;
        }
        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
            points += 1;
        }
        if (Boolean.TRUE.equals(owner.getHouseholdGold())) {
            points += 2;
        }
        if (FiscalYear.of(LocalDate.now()) - FiscalYear.of(owner.getRegistrationDate()) > 1) {
            points += 3;
        }
        return points;
    }

    /** Membership level (1-4) for a points total. */
    public static int level(int points) {
        if (points >= 6) {
            return 4;
        }
        if (points >= 4) {
            return 3;
        }
        if (points >= 2) {
            return 2;
        }
        return 1;
    }
}
package org.springframework.samples.petclinic.util;

import java.util.concurrent.atomic.AtomicLong;

import org.slf4j.LoggerFactory;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Emits the immutable {@code OWNER_CREATED} structured event to the {@code AUDIT} logger,
 * carrying a monotonically increasing {@code seq}, the owner id, the owner's current
 * primary identifier and the membership level.
 *
 * <p>The primary identifier is resolved via {@link #primaryIdentifier(Owner)}: today the
 * owner's {@code customerCode}, and whatever replaces it later (e.g. the memberId).
 */
public final class OwnerCreatedEvent {

    private static final AtomicLong SEQ = new AtomicLong();

    private OwnerCreatedEvent() {
    }

    /** The owner's current primary identifier. */
    public static String primaryIdentifier(Owner owner) {
        return owner.getCustomerCode();
    }

    /** Emits {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}. */
    public static void emit(Owner owner, Object membershipLevel) {
        LoggerFactory.getLogger("AUDIT").info(
            "{\"seq\":{},\"ownerId\":{},\"customerCode\":\"{}\",\"membershipLevel\":\"{}\",\"event\":\"OWNER_CREATED\"}",
            SEQ.incrementAndGet(), owner.getId(), primaryIdentifier(owner), membershipLevel);
    }
}

